"""Generate one Python module beside each application-owned Designer form."""

from __future__ import annotations

import argparse
import ast
import hashlib
import subprocess
import sys
from importlib.metadata import version
from pathlib import Path
from xml.etree import ElementTree

ROOT = Path(__file__).resolve().parents[2]
GENERATED_MARKER = "# Generated by LiveVoiceBridge .github/scripts/generate_ui.py; DO NOT EDIT.\n"
FORM_DIRECTORIES = (
    "src/livevoicebridge/desktop/resources/forms",
    "src/livevoicebridge/plugins/builtin",
)
UIC_TIMEOUT_SECONDS = 60


def form_sources(root: Path) -> list[Path]:
    return sorted(path for directory in FORM_DIRECTORIES for path in (root / directory).rglob("*.ui"))


def generated_path(source: Path) -> Path:
    return source.with_name(f"ui_{source.stem}.py")


def generated_module(root: Path, source: Path) -> str:
    return ".".join(generated_path(source).relative_to(root / "src").with_suffix("").parts)


def generation_inputs(root: Path, python: str) -> tuple[list[Path], bytes, list[str]]:
    sources = form_sources(root)
    if not sources:
        raise ValueError("No application Designer forms were found.")
    # Resolve the tool from the selected environment without importing Qt or its Python wrapper.
    print("Locating Designer compiler in the selected Python environment", flush=True)
    locate = (
        "import sys; from importlib.metadata import distribution; "
        "tool = 'PySide6/uic.exe' if sys.platform == 'win32' else 'PySide6/Qt/libexec/uic'; "
        "print(distribution('PySide6_Essentials').locate_file(tool))"
    )
    executable = Path(
        subprocess.check_output(
            [python, "-B", "-c", locate],
            encoding="utf-8",
            stdin=subprocess.DEVNULL,
            timeout=UIC_TIMEOUT_SECONDS,
        ).strip()
    )
    if not executable.is_file():
        raise FileNotFoundError(f"Designer compiler is missing: {executable}")
    command = [str(executable), "-g", "python"]
    print(f"Checking Designer compiler version: {executable}", flush=True)
    compiler = subprocess.check_output(
        [*command, "--version"],
        encoding="utf-8",
        stderr=subprocess.STDOUT,
        stdin=subprocess.DEVNULL,
        timeout=UIC_TIMEOUT_SECONDS,
    ).strip()
    print(f"Designer compiler: {compiler}", flush=True)
    return sources, Path(__file__).read_bytes() + compiler.encode("utf-8"), command


def generated_header(source: Path, signature: bytes) -> str:
    digest = hashlib.sha256(signature + source.read_bytes()).hexdigest()
    return GENERATED_MARKER + f"# Input and compiler fingerprint: {digest}\n"


def obsolete_forms(root: Path, targets: set[Path]) -> list[Path]:
    obsolete = []
    for directory in FORM_DIRECTORIES:
        for path in (root / directory).rglob("ui_*.py"):
            if path not in targets and path.read_text(encoding="utf-8").startswith(GENERATED_MARKER):
                obsolete.append(path)
    return sorted(obsolete)


def check_generated(root: Path = ROOT, python: str = sys.executable) -> bool:
    sources, signature, _ = generation_inputs(root, python)
    issues = []
    for source in sources:
        target = generated_path(source)
        if not target.is_file() or not target.read_text(encoding="utf-8").startswith(
            generated_header(source, signature)
        ):
            issues.append(f"Missing or outdated form: {target.relative_to(root)}")
    for path in obsolete_forms(root, {generated_path(source) for source in sources}):
        issues.append(f"Obsolete form: {path.relative_to(root)}")
    if issues:
        print("\n".join(issues), file=sys.stderr)
        print("Run .github/scripts/generate_ui.py with the project Python before starting.", file=sys.stderr)
        return False
    print(f"Generated forms are current: {len(sources)}")
    return True


def generate(root: Path = ROOT, python: str = sys.executable, *, force: bool = False) -> None:
    sources, signature, command = generation_inputs(root, python)
    for path in obsolete_forms(root, {generated_path(source) for source in sources}):
        path.unlink()
        print(f"Removed obsolete form: {path.relative_to(root)}")
    for source in sources:
        target = generated_path(source)
        header = generated_header(source, signature)
        previous = target.read_text(encoding="utf-8") if target.exists() else ""
        if previous and not previous.startswith(GENERATED_MARKER):
            raise ValueError(f"Refusing to overwrite a non-generated file: {target}")
        if not force and previous.startswith(header):
            continue
        document = ElementTree.parse(source).getroot()
        form_class = document.findtext("class", "")
        widget = document.find("widget")
        root_class = widget.get("class", "") if widget is not None else ""
        if not form_class.isidentifier() or not root_class.isidentifier():
            raise ValueError(f"Invalid Designer form/root class: {source}")
        custom_roots = {
            item.findtext("class"): item.findtext("header") for item in document.findall("customwidgets/customwidget")
        }
        root_module = custom_roots.get(root_class, "PySide6.QtWidgets")
        if not root_module or not all(part.isidentifier() for part in root_module.split(".")):
            raise ValueError(f"Invalid root widget import: {source}")
        print(f"Compiling Designer form: {source.relative_to(root)}", flush=True)
        compiled = subprocess.check_output(
            [*command, source.name],
            cwd=source.parent,
            encoding="utf-8",
            stdin=subprocess.DEVNULL,
            timeout=UIC_TIMEOUT_SECONDS,
        )
        factory = (
            f"\n\nfrom {root_module} import {root_class} as _FormRoot\n"
            "from livevoicebridge.desktop.forms import setup_form as _setup_form\n\n\n"
            "def create_form(root: _FormRoot | None = None) -> _FormRoot:\n"
            f"    return _setup_form(Ui_{form_class}(), _FormRoot, root)\n"
        )
        result = header + compiled + factory
        ast.parse(result, filename=str(target))
        target.write_text(result, encoding="utf-8", newline="\n")
        print(f"Generated form: {target.relative_to(root)}", flush=True)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--force", action="store_true", help="Regenerate every form, including unchanged inputs.")
    mode.add_argument(
        "--check", action="store_true", help="Check for missing, outdated or obsolete forms without writing."
    )
    args = parser.parse_args()
    print(f"Designer compiler: PySide6 {version('PySide6')}")
    if args.check:
        if not check_generated():
            raise SystemExit(1)
    else:
        generate(force=args.force)


if __name__ == "__main__":
    try:
        main()
    except subprocess.CalledProcessError as exc:
        raise SystemExit(exc.returncode) from exc
    except subprocess.TimeoutExpired as exc:
        print(f"Designer compiler command timed out after {exc.timeout}s: {exc.cmd}", file=sys.stderr)
        raise SystemExit(1) from exc
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(1) from exc
